local.schema:
enum SafetyCheckOutcome { ACTIVE OK ALARM CANCELLED }

type SafetyCheck {
    id: OID!
    startedAt: DateTime!
    durationMinutes: Int!
    note: String
    contactIds: [OID!]!
    endedAt: DateTime
    outcome: SafetyCheckOutcome!
}

type RiskyPlace {
    id: OID!
    label: String!
    lat: Float!
    lng: Float!
    radiusM: Int!
    planId: OID
}

type QuitJourneyLocalState {
    safetyChecks: [SafetyCheck!]
    riskyPlaces: [RiskyPlace!]
}

operations.reducer:
const i = action.input;
if (i.unitsPerDay <= 0 || i.unitsPerPack <= 0 || i.packPrice < 0 || (i.standardDrinkGrams != null && (i.standardDrinkGrams < 5 || i.standardDrinkGrams > 30))) {
  throw new InvalidQuitPlanError("unitsPerDay and unitsPerPack must be positive and packPrice must not be negative");
}
let dailyLimit: number | null = null;
if (i.goal === "REDUCTION") {
  if (i.dailyLimit == null || i.dailyLimit <= 0 || i.dailyLimit >= i.unitsPerDay) {
    throw new InvalidReductionGoalError("A reduction goal needs a daily limit above 0 and below your current daily amount");
  }
  dailyLimit = i.dailyLimit;
}
state.plan = {
  quitDateTime: i.quitDateTime,
  productType: i.productType,
  unitsPerDay: i.unitsPerDay,
  unitsPerPack: i.unitsPerPack,
  packPrice: i.packPrice,
  currency: i.currency,
  yearsSmoked: i.yearsSmoked ?? null,
  customName: i.customName?.trim() || null,
  unitLabel: i.unitLabel?.trim() || null,
  goal: i.goal ?? null,
  dailyLimit,
  standardDrinkGrams: i.standardDrinkGrams ?? null,
};

operations.schema:
input SetDisplayNameInput {
    displayName: String
}

input AddMotivationInput {
    id: OID!
    text: String!
    imageUrl: URL
}

operations.reducer:
const text = action.input.text.trim();
if (!text) {
  throw new EmptyMotivationError("Motivation text must not be empty");
}
state.motivations.push({ id: action.input.id, text, imageUrl: action.input.imageUrl || null });

operations.schema:
input RemoveMotivationInput {
    id: OID!
}

operations.reducer:
const index = state.motivations.findIndex((m) => m.id === action.input.id);
if (index === -1) {
  throw new MotivationNotFoundError(`Motivation ${action.input.id} not found`);
}
state.motivations.splice(index, 1);

operations.schema:
input TogglePrepTaskInput {
    taskKey: String!
    done: Boolean!
}

operations.reducer:
const key = action.input.taskKey;
const has = state.prepTasksDone.includes(key);
if (action.input.done && !has) {
  state.prepTasksDone.push(key);
} else if (!action.input.done && has) {
  state.prepTasksDone = state.prepTasksDone.filter((k) => k !== key);
}

const i = action.input;
const validIntensity = (n: number) => Number.isInteger(n) && n >= 1 && n <= 5;
if (!validIntensity(i.intensity) || (i.intensityAfter != null && !validIntensity(i.intensityAfter))) {
  throw new InvalidCravingIntensityError("Intensity must be an integer between 1 and 5");
}
if (i.durationMinutes != null && i.durationMinutes < 0) {
  throw new InvalidCravingDurationError("Duration must not be negative");
}
state.cravings.push({
  id: i.id,
  timestamp: i.timestamp,
  intensity: i.intensity,
  trigger: i.trigger,
  strategy: i.strategy ?? null,
  outcome: i.outcome,
  durationMinutes: i.durationMinutes ?? null,
  note: i.note || null,
  intensityAfter: i.intensityAfter ?? null,
});

operations.schema:
input DeleteCravingInput {
    id: OID!
}

operations.reducer:
const index = state.cravings.findIndex((c) => c.id === action.input.id);
if (index === -1) {
  throw new CravingNotFoundError(`Craving ${action.input.id} not found`);
}
state.cravings.splice(index, 1);

const i = action.input;
if (i.units <= 0) {
  throw new InvalidSlipUnitsError("Units smoked must be positive");
}
state.slips.push({
  id: i.id,
  timestamp: i.timestamp,
  units: i.units,
  trigger: i.trigger ?? null,
  note: i.note || null,
});

operations.schema:
input DeleteSlipInput {
    id: OID!
}

operations.reducer:
const index = state.slips.findIndex((s) => s.id === action.input.id);
if (index === -1) {
  throw new SlipNotFoundError(`Slip ${action.input.id} not found`);
}
state.slips.splice(index, 1);

operations.schema:
input RestartJourneyInput {
    attemptId: OID!
    endedAt: DateTime!
    newQuitDateTime: DateTime!
    reason: String
}

operations.reducer:
const i = action.input;
if (!state.plan) {
  throw new NoActiveQuitPlanError("There is no quit plan to restart");
}
const previousQuit = Date.parse(state.plan.quitDateTime);
if (Date.parse(i.endedAt) < previousQuit || Date.parse(i.newQuitDateTime) < Date.parse(i.endedAt)) {
  throw new InvalidRestartDatesError("endedAt must be after the current quit date and the new quit date must not be before endedAt");
}
state.pastAttempts.push({
  id: i.attemptId,
  quitDateTime: state.plan.quitDateTime,
  endedAt: i.endedAt,
  reason: i.reason || null,
});
state.plan.quitDateTime = i.newQuitDateTime;

const i = action.input;
if (!/^\d{4}-\d{2}-\d{2}$/.test(i.date)) {
  throw new InvalidCheckinDateError("Check-in date must be a calendar date in YYYY-MM-DD format");
}
if (state.checkIns.some((c) => c.date === i.date)) {
  throw new DuplicateCheckinDateError(`A check-in for ${i.date} already exists`);
}
const ratings = [i.mood, i.cravingLevel, i.energy, i.sleepQuality].filter((r) => r != null);
if (ratings.some((r) => !Number.isInteger(r) || r < 1 || r > 5)) {
  throw new InvalidCheckinRatingError("Ratings must be integers between 1 and 5");
}
if (i.weightKg != null && i.weightKg <= 0) {
  throw new InvalidWeightError("Weight must be positive");
}
state.checkIns.push({
  id: i.id,
  date: i.date,
  mood: i.mood,
  cravingLevel: i.cravingLevel,
  energy: i.energy ?? null,
  sleepQuality: i.sleepQuality ?? null,
  weightKg: i.weightKg ?? null,
  symptoms: i.symptoms ?? [],
  note: i.note || null,
});

operations.schema:
input DeleteCheckInInput {
    id: OID!
}

operations.reducer:
const index = state.checkIns.findIndex((c) => c.id === action.input.id);
if (index === -1) {
  throw new CheckinNotFoundError(`Check-in ${action.input.id} not found`);
}
state.checkIns.splice(index, 1);

operations.schema:
input AddRewardGoalInput {
    id: OID!
    title: String!
    cost: Float!
    emoji: String
}

operations.reducer:
const title = action.input.title.trim();
if (!title || action.input.cost <= 0) {
  throw new InvalidRewardGoalError("Reward needs a title and a positive cost");
}
state.rewards.push({ id: action.input.id, title, cost: action.input.cost, emoji: action.input.emoji || null, claimedAt: null });

operations.schema:
input ClaimRewardInput {
    id: OID!
    claimedAt: DateTime!
}

operations.reducer:
const reward = state.rewards.find((r) => r.id === action.input.id);
if (!reward) {
  throw new RewardNotFoundError(`Reward ${action.input.id} not found`);
}
if (reward.claimedAt) {
  throw new RewardAlreadyClaimedError("Reward was already claimed");
}
const plan = state.plan;
if (!plan) {
  throw new InsufficientSavingsError("Set a quit plan before claiming rewards");
}
const at = Date.parse(action.input.claimedAt);
const periods = state.pastAttempts.map((a) => [Date.parse(a.quitDateTime), Date.parse(a.endedAt)]);
periods.push([Date.parse(plan.quitDateTime), at]);
let units = 0;
for (const [start, end] of periods) {
  if (end <= start) continue;
  const slipped = state.slips
    .filter((s) => { const t = Date.parse(s.timestamp); return t >= start && t <= end; })
    .reduce((sum, s) => sum + s.units, 0);
  units += Math.max(0, ((end - start) / 86400000) * plan.unitsPerDay - slipped);
}
const earned = units * (plan.packPrice / plan.unitsPerPack);
const spent = state.rewards.reduce((sum, r) => sum + (r.claimedAt ? r.cost : 0), 0);
if (earned - spent < reward.cost) {
  throw new InsufficientSavingsError(`Not enough savings yet: ${(earned - spent).toFixed(2)} available, ${reward.cost.toFixed(2)} needed`);
}
reward.claimedAt = action.input.claimedAt;

operations.schema:
input DeleteRewardGoalInput {
    id: OID!
}

operations.reducer:
const index = state.rewards.findIndex((r) => r.id === action.input.id);
if (index === -1) {
  throw new RewardGoalToDeleteNotFoundError(`Reward ${action.input.id} not found`);
}
state.rewards.splice(index, 1);

operations.schema:
input EndQuitAidInput {
    id: OID!
    endedAt: DateTime!
}

operations.reducer:
const aid = state.aids.find((a) => a.id === action.input.id);
if (!aid) {
  throw new QuitAidNotFoundError(`Quit aid ${action.input.id} not found`);
}
aid.endedAt = action.input.endedAt;

const i = action.input;
if (!state.aids.some((a) => a.id === i.aidId)) {
  throw new AidForUseNotFoundError(`Quit aid ${i.aidId} not found`);
}
state.aidUses.push({ id: i.id, aidId: i.aidId, timestamp: i.timestamp, note: i.note || null, beforeDrinking: i.beforeDrinking ?? null });

operations.schema:
input AddSupportContactInput {
    id: OID!
    name: String!
    phone: String
    relation: String
}

operations.reducer:
const name = action.input.name.trim();
if (!name) {
  throw new EmptyContactNameError("Contact name must not be empty");
}
state.supportContacts.push({ id: action.input.id, name, phone: action.input.phone || null, relation: action.input.relation || null });

operations.schema:
input RemoveSupportContactInput {
    id: OID!
}

operations.reducer:
const index = state.supportContacts.findIndex((c) => c.id === action.input.id);
if (index === -1) {
  throw new SupportContactNotFoundError(`Contact ${action.input.id} not found`);
}
state.supportContacts.splice(index, 1);

operations.schema:
input SetQuitlineInput {
    phone: String
}

operations.reducer:
const i = action.input;
if (i.expiresOn && !/^\d{4}-\d{2}-\d{2}$/.test(i.expiresOn)) {
  throw new InvalidNaloxoneExpiryError("Expiry date must be a calendar date in YYYY-MM-DD format");
}
(state.naloxoneKits ??= []).push({ id: i.id, kind: i.kind, location: i.location?.trim() || null, expiresOn: i.expiresOn || null, addedAt: i.addedAt, usedAt: null });

operations.schema:
input MarkNaloxoneUsedInput {
    id: OID!
    usedAt: DateTime!
}

operations.reducer:
const kit = (state.naloxoneKits ?? []).find((k) => k.id === action.input.id);
if (!kit) {
  throw new NaloxoneKitNotFoundError(`Naloxone kit ${action.input.id} not found`);
}
kit.usedAt = action.input.usedAt;

operations.schema:
input RemoveNaloxoneKitInput {
    id: OID!
}

operations.reducer:
const index = (state.naloxoneKits ?? []).findIndex((x) => x.id === action.input.id);
if (index === -1) {
  throw new NaloxoneKitToRemoveNotFoundError(`Naloxone kit ${action.input.id} not found`);
}
state.naloxoneKits?.splice(index, 1);

operations.schema:
input DeleteDrugCheckInput {
    id: OID!
}

operations.reducer:
const index = (state.drugChecks ?? []).findIndex((x) => x.id === action.input.id);
if (index === -1) {
  throw new DrugCheckNotFoundError(`Drug check ${action.input.id} not found`);
}
state.drugChecks?.splice(index, 1);

const i = action.input;
if (!/^\d{4}-\d{2}-\d{2}$/.test(i.startDate) || (i.endDate != null && (!/^\d{4}-\d{2}-\d{2}$/.test(i.endDate) || i.endDate < i.startDate))) {
  throw new InvalidExclusionError("Dates must be YYYY-MM-DD and the end date must not be before the start date");
}
(state.exclusions ??= []).push({ id: i.id, scheme: i.scheme, startDate: i.startDate, endDate: i.endDate ?? null, note: i.note || null });

operations.schema:
input DeleteExclusionInput {
    id: OID!
}

operations.reducer:
const index = (state.exclusions ?? []).findIndex((x) => x.id === action.input.id);
if (index === -1) {
  throw new ExclusionNotFoundError(`Exclusion ${action.input.id} not found`);
}
state.exclusions?.splice(index, 1);

const i = action.input;
if (!Number.isInteger(i.durationMinutes) || i.durationMinutes < 1 || i.durationMinutes > 240) {
  throw new InvalidSafetyDurationError("Duration must be between 1 and 240 minutes");
}
if ((state.safetyChecks ?? []).some((c) => c.outcome === "ACTIVE")) {
  throw new SafetyCheckAlreadyActiveError("A safety check is already running");
}
(state.safetyChecks ??= []).push({ id: i.id, startedAt: i.startedAt, durationMinutes: i.durationMinutes, note: i.note || null, contactIds: i.contactIds ?? [], endedAt: null, outcome: "ACTIVE" });

operations.schema:
input EndSafetyCheckInput {
    id: OID!
    endedAt: DateTime!
    outcome: SafetyCheckOutcome!
}

operations.reducer:
const check = (state.safetyChecks ?? []).find((c) => c.id === action.input.id);
if (!check) {
  throw new SafetyCheckNotFoundError(`Safety check ${action.input.id} not found`);
}
if (check.outcome !== "ACTIVE" || action.input.outcome === "ACTIVE") {
  throw new InvalidSafetyCheckEndError("Only an active check can be ended, and not with outcome ACTIVE");
}
check.endedAt = action.input.endedAt;
check.outcome = action.input.outcome;

const i = action.input;
const label = i.label.trim();
if (!label || i.lat < -90 || i.lat > 90 || i.lng < -180 || i.lng > 180 || i.radiusM < 25 || i.radiusM > 5000) {
  throw new InvalidRiskyPlaceError("A place needs a name, valid coordinates and a radius of 25-5000 m");
}
(state.riskyPlaces ??= []).push({ id: i.id, label, lat: i.lat, lng: i.lng, radiusM: i.radiusM, planId: i.planId ?? null });

operations.schema:
input DeleteRiskyPlaceInput {
    id: OID!
}

operations.reducer:
const index = (state.riskyPlaces ?? []).findIndex((x) => x.id === action.input.id);
if (index === -1) {
  throw new RiskyPlaceNotFoundError(`Place ${action.input.id} not found`);
}
state.riskyPlaces?.splice(index, 1);

const i = action.input;
const ifText = i.ifText.trim();
const thenText = i.thenText.trim();
if (!ifText || !thenText) {
  throw new InvalidIfThenPlanError("Both the 'if' and the 'then' part are needed");
}
(state.ifThenPlans ??= []).push({ id: i.id, trigger: i.trigger ?? null, ifText, thenText, strategy: i.strategy ?? null, createdAt: i.createdAt, lastReviewedAt: null });

const i = action.input;
const plan = (state.ifThenPlans ?? []).find((p) => p.id === i.id);
if (!plan) {
  throw new IfThenPlanNotFoundError(`Plan ${i.id} not found`);
}
const ifText = i.ifText.trim();
const thenText = i.thenText.trim();
if (!ifText || !thenText) {
  throw new InvalidIfThenPlanUpdateError("Both the 'if' and the 'then' part are needed");
}
plan.trigger = i.trigger ?? null;
plan.ifText = ifText;
plan.thenText = thenText;
plan.strategy = i.strategy ?? null;

operations.schema:
input ReviewIfThenPlanInput {
    id: OID!
    reviewedAt: DateTime!
}

operations.reducer:
const plan = (state.ifThenPlans ?? []).find((p) => p.id === action.input.id);
if (!plan) {
  throw new IfThenPlanToReviewNotFoundError(`Plan ${action.input.id} not found`);
}
plan.lastReviewedAt = action.input.reviewedAt;

operations.schema:
input DeleteIfThenPlanInput {
    id: OID!
}

operations.reducer:
const index = (state.ifThenPlans ?? []).findIndex((x) => x.id === action.input.id);
if (index === -1) {
  throw new IfThenPlanToDeleteNotFoundError(`Plan ${action.input.id} not found`);
}
state.ifThenPlans?.splice(index, 1);

const i = action.input;
if (i.volumeMl <= 0 || i.volumeMl > 5000 || i.abvPercent <= 0 || i.abvPercent > 100) {
  throw new InvalidDrinkError("Volume must be 1-5000 ml and ABV between 0 and 100 %");
}
// Ethanol density 0.789 g/ml; standard-drink size defaults to the WHO's 10 g.
const gramsAlcohol = Math.round(i.volumeMl * (i.abvPercent / 100) * 0.789 * 10) / 10;
const standardDrinks = Math.round((gramsAlcohol / (state.plan?.standardDrinkGrams ?? 10)) * 10) / 10;
(state.drinks ??= []).push({ id: i.id, timestamp: i.timestamp, beverage: i.beverage, volumeMl: i.volumeMl, abvPercent: i.abvPercent, gramsAlcohol, standardDrinks, slipId: i.slipId });
state.slips.push({ id: i.slipId, timestamp: i.timestamp, units: standardDrinks, trigger: null, note: i.note || null });

operations.schema:
input DeleteDrinkInput {
    id: OID!
}

operations.reducer:
const drinks = state.drinks ?? [];
const drink = drinks.find((d) => d.id === action.input.id);
if (!drink) {
  throw new DrinkNotFoundError(`Drink ${action.input.id} not found`);
}
state.drinks = drinks.filter((d) => d.id !== drink.id);
state.slips = state.slips.filter((s) => s.id !== drink.slipId);

operations.schema:
input LogScreenTimeInput {
    id: OID!
    date: String!
    minutes: Int!
}

operations.reducer:
const i = action.input;
if (!/^\d{4}-\d{2}-\d{2}$/.test(i.date) || !Number.isInteger(i.minutes) || i.minutes < 0 || i.minutes > 1440) {
  throw new InvalidScreenTimeError("Date must be YYYY-MM-DD and minutes 0-1440");
}
const list = (state.screenTime ??= []);
const existing = list.find((e) => e.date === i.date);
if (existing) {
  existing.minutes = i.minutes;
} else {
  list.push({ id: i.id, date: i.date, minutes: i.minutes });
}

operations.schema:
input LogGamblingLossInput {
    id: OID!
    date: String!
    amount: Float!
    note: String
}

operations.reducer:
const i = action.input;
if (!/^\d{4}-\d{2}-\d{2}$/.test(i.date) || i.amount <= 0) {
  throw new InvalidGamblingLossError("Date must be YYYY-MM-DD and the amount above 0");
}
(state.gamblingLosses ??= []).push({ id: i.id, date: i.date, amount: i.amount, note: i.note || null });

operations.schema:
input DeleteGamblingLossInput {
    id: OID!
}

operations.reducer:
const index = (state.gamblingLosses ?? []).findIndex((x) => x.id === action.input.id);
if (index === -1) {
  throw new GamblingLossNotFoundError(`Loss ${action.input.id} not found`);
}
state.gamblingLosses?.splice(index, 1);

operations.schema:
input RecordAssessmentInput {
    id: OID!
    instrument: AssessmentInstrument!
    takenAt: DateTime!
    answers: [Int!]!
}

operations.reducer:
const i = action.input;
// [number of items, lowest answer, highest answer] per instrument.
const shape: Record<string, [number, number, number]> = {
  AUDIT_C: [3, 0, 4], AUDIT: [10, 0, 4], HSI: [2, 0, 3], CUDIT_R: [8, 0, 4], PGSI: [9, 0, 3],
  BARC_10: [10, 1, 6], SOWS: [16, 0, 4], SAWS: [10, 0, 3], CWS: [19, 0, 10], ACSA: [16, 0, 4],
};
const [count, min, max] = shape[i.instrument];
if (i.answers.length !== count || i.answers.some((a) => !Number.isInteger(a) || a < min || a > max)) {
  throw new InvalidAssessmentAnswersError(`${i.instrument} needs ${count} answers between ${min} and ${max}`);
}
(state.assessments ??= []).push({ id: i.id, instrument: i.instrument, takenAt: i.takenAt, answers: i.answers, score: i.answers.reduce((sum, a) => sum + a, 0) });

operations.schema:
input DeleteAssessmentInput {
    id: OID!
}

operations.reducer:
const index = (state.assessments ?? []).findIndex((x) => x.id === action.input.id);
if (index === -1) {
  throw new AssessmentNotFoundError(`Assessment ${action.input.id} not found`);
}
state.assessments?.splice(index, 1);

const i = action.input;
if (!state.aids.some((a) => a.id === i.aidId)) {
  throw new MedicationAidNotFoundError(`Quit aid ${i.aidId} not found`);
}
const ordered = i.steps.every((s, n) => n === 0 || s.fromDay > i.steps[n - 1].fromDay);
const valid = i.steps.every((s) => Number.isInteger(s.fromDay) && s.fromDay >= 1 && s.dose.trim() !== "" && Number.isInteger(s.timesPerDay) && s.timesPerDay >= 1);
if (!/^\d{4}-\d{2}-\d{2}$/.test(i.startDate) || i.steps.length === 0 || i.steps[0].fromDay !== 1 || !ordered || !valid) {
  throw new InvalidMedicationPlanError("A plan needs a YYYY-MM-DD start date and steps starting on day 1 in increasing day order, each with a dose and at least one time per day");
}
const plans = (state.medicationPlans ??= []).filter((p) => p.aidId !== i.aidId);
plans.push({ id: i.id, aidId: i.aidId, source: i.source, startDate: i.startDate, steps: i.steps.map((s) => ({ id: s.id, fromDay: s.fromDay, dose: s.dose.trim(), timesPerDay: s.timesPerDay })), note: i.note || null });
state.medicationPlans = plans;

operations.schema:
input ClearMedicationPlanInput {
    aidId: OID!
}

operations.reducer:
const plans = state.medicationPlans ?? [];
if (!plans.some((p) => p.aidId === action.input.aidId)) {
  throw new MedicationPlanNotFoundError(`No plan for quit aid ${action.input.aidId}`);
}
state.medicationPlans = plans.filter((p) => p.aidId !== action.input.aidId);

operations.schema:
input RecordTakeHomeInput {
    id: OID!
    aidId: OID!
    pickedUpOn: String!
    doses: Int!
}

operations.reducer:
const i = action.input;
if (!state.aids.some((a) => a.id === i.aidId)) {
  throw new TakeHomeAidNotFoundError(`Quit aid ${i.aidId} not found`);
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(i.pickedUpOn) || !Number.isInteger(i.doses) || i.doses < 1 || i.doses > 31) {
  throw new InvalidTakeHomeError("Pick-up date must be YYYY-MM-DD and doses 1-31");
}
(state.takeHomes ??= []).push({ id: i.id, aidId: i.aidId, pickedUpOn: i.pickedUpOn, doses: i.doses });

operations.schema:
input StartProgramInput {
    id: OID!
    program: ProgramKey!
    startedAt: DateTime!
}

operations.reducer:
const i = action.input;
if ((state.programs ?? []).some((p) => p.program === i.program && !p.endedAt)) {
  throw new ProgramAlreadyActiveError(`${i.program} is already running`);
}
(state.programs ??= []).push({ id: i.id, program: i.program, startedAt: i.startedAt, completedMissions: [], endedAt: null });

operations.schema:
input CompleteMissionInput {
    programId: OID!
    missionKey: String!
}

operations.reducer:
const program = (state.programs ?? []).find((p) => p.id === action.input.programId);
if (!program) {
  throw new ProgramNotFoundError(`Program ${action.input.programId} not found`);
}
if (program.endedAt) {
  throw new ProgramNotActiveError("The program has ended");
}
if (!program.completedMissions.includes(action.input.missionKey)) {
  program.completedMissions.push(action.input.missionKey);
}

operations.schema:
input EndProgramInput {
    programId: OID!
    endedAt: DateTime!
}

operations.reducer:
const program = (state.programs ?? []).find((p) => p.id === action.input.programId);
if (!program) {
  throw new ProgramToEndNotFoundError(`Program ${action.input.programId} not found`);
}
if (program.endedAt) {
  throw new ProgramAlreadyEndedError("The program has already ended");
}
program.endedAt = action.input.endedAt;
